import { api } from './api';

/**
 * One place for Web-Push plumbing. The service worker itself is the PWA
 * worker generated by vite-plugin-pwa (it importScripts /push-sw.js), so we
 * never register a second worker — we only manage the subscription.
 */

export type PushSupport = 'ready' | 'unsupported' | 'insecure';

export function pushSupport(): PushSupport {
  if (typeof window === 'undefined') return 'unsupported';
  if (!window.isSecureContext) return 'insecure';
  if (!('serviceWorker' in navigator) || !('PushManager' in window) || !('Notification' in window)) {
    return 'unsupported';
  }
  return 'ready';
}

export type PushState = 'subscribed' | 'unsubscribed' | 'denied' | 'default' | 'unsupported' | 'insecure';

export async function currentPushState(): Promise<PushState> {
  const support = pushSupport();
  if (support !== 'ready') return support;
  if (Notification.permission === 'denied') return 'denied';
  if (Notification.permission === 'default') return 'default';
  try {
    const registration = await navigator.serviceWorker.ready;
    const subscription = await registration.pushManager.getSubscription();
    return subscription ? 'subscribed' : 'unsubscribed';
  } catch {
    return 'unsubscribed';
  }
}

function urlBase64ToUint8Array(base64String: string): Uint8Array {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; i += 1) outputArray[i] = rawData.charCodeAt(i);
  return outputArray;
}

export type EnablePushResult = 'subscribed' | 'denied' | 'unsupported' | 'insecure' | 'server-off' | 'error';

/**
 * Ask for permission (when needed) and create/persist this device's push
 * subscription. Never throws — the caller renders the outcome.
 */
export async function enablePush(): Promise<EnablePushResult> {
  const support = pushSupport();
  if (support !== 'ready') return support;
  try {
    const server = await api.get<{ data: { enabled: boolean; publicKey: string | null } }>('/api/push/public-key');
    if (!server.data.enabled || !server.data.publicKey) return 'server-off';

    let permission = Notification.permission;
    if (permission === 'default') permission = await Notification.requestPermission();
    if (permission !== 'granted') return 'denied';

    const registration = await navigator.serviceWorker.ready;
    let subscription = await registration.pushManager.getSubscription();
    if (!subscription) {
      subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(server.data.publicKey) as BufferSource,
      });
    }
    await api.post('/api/push/subscribe', subscription.toJSON());
    return 'subscribed';
  } catch {
    return 'error';
  }
}

export async function disablePush(): Promise<void> {
  if (pushSupport() !== 'ready') return;
  try {
    const registration = await navigator.serviceWorker.ready;
    const subscription = await registration.pushManager.getSubscription();
    if (subscription) {
      await api.post('/api/push/unsubscribe', { endpoint: subscription.endpoint }).catch(() => undefined);
      await subscription.unsubscribe().catch(() => undefined);
    }
  } catch {
    /* best effort */
  }
}
